type Config struct{ Hosts []string }

var published atomic.Pointer[Config]

func load() *Config { return published.Load() }      // readers never lock
func update(add string) {                            // writer: copy, then swap
    old := published.Load()
    next := &Config{Hosts: append(slices.Clone(old.Hosts), add)}
    published.Store(next)
}
